// スプレッドシートを開いた時に専用メニューを作る設定
function onOpen() {
  const ui = SpreadsheetApp.getUi();
  ui.createMenu('📅 スケジュール抽出')
    .addItem('実行する', 'findFullSchedule')
    .addToUi();
}

function findFullSchedule() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const mainSheet = ss.getSheetByName('メイン');

  const planName = mainSheet.getRange('B1').getValue();
  const variableMember = mainSheet.getRange('B2').getValue();
  const firstStartDateVal = mainSheet.getRange('B3').getValue();

  if (!planName) {
    Browser.msgBox('メインシートのB1セルでプラン（自社建材ブランド または 自社商品）を選択してください。');
    return;
  }
  if (!firstStartDateVal) {
    Browser.msgBox('メインシートのB3セルに「初回検索開始日」（例: 2026/04/01）を入力してください。');
    return;
  }

  let baseDate = new Date(firstStartDateVal);
  baseDate.setHours(0, 0, 0, 0);

  // ★ここで正式名称「自社商品」を判定するように修正しました
  let settingSheetName = '';
  if (planName === '自社建材ブランド') {
    settingSheetName = '自社建材ブランド設定';
  } else if (planName === '自社商品') { 
    settingSheetName = '自社商品設定';
  } else {
    // どちらでもない文字が入っていた場合のエラーメッセージ
    Browser.msgBox('メインシートのB1セルのプラン名（' + planName + '）が正しくありません。');
    return;
  }

  const settingSheet = ss.getSheetByName(settingSheetName);

  // ★もしシート名が見つからなかった場合のエラー処理を追加（先ほどのエラー対策です）
  if (!settingSheet) {
    Browser.msgBox('「' + settingSheetName + '」という名前のシートが見つかりません。シート名にスペース等が混じっていないか確認してください。');
    return;
  }

  const resultSheet = ss.getSheetByName('空き時間');

  resultSheet.clear();
  resultSheet.appendRow(['【 ' + planName + ' 】の最短スケジュール案（土日限定）']); 
  resultSheet.appendRow(['打合せ名', '日付', '開始時刻', '終了時刻', '参加者']);

  const lastRow = settingSheet.getLastRow();
  if(lastRow < 2) return; 
  const data = settingSheet.getRange(2, 1, lastRow - 1, 4).getValues();

  const bufferMin = 60;    
  const daysToSearch = 60; 

  for(let i = 0; i < data.length; i++) {
    let meetingName = data[i][0];
    let durationMin = data[i][1];
    let membersRaw = data[i][2];
    let intervalDays = data[i][3];

    if(!meetingName || !durationMin || !membersRaw) continue;

    if (variableMember) {
      membersRaw = String(membersRaw).replace('[変動担当者]', variableMember);
    }
    let members = String(membersRaw).split(',').map(m => m.trim());

    let searchStartDay = new Date(baseDate);
    searchStartDay.setDate(searchStartDay.getDate() + Number(intervalDays));
    searchStartDay.setHours(0, 0, 0, 0);

    let searchEndDay = new Date(searchStartDay);
    searchEndDay.setDate(searchEndDay.getDate() + daysToSearch);
    searchEndDay.setHours(23, 59, 59, 999);

    let allMemberEvents = [];
    for (let j = 0; j < members.length; j++) {
      let cal = CalendarApp.getCalendarById(members[j]);
      if (cal) {
        allMemberEvents.push(cal.getEvents(searchStartDay, searchEndDay));
      }
    }

    let firstFoundDate = null; 

    for (let d = 0; d < daysToSearch; d++) {
      let checkDate = new Date(searchStartDay);
      checkDate.setDate(searchStartDay.getDate() + d);

      let dayOfWeek = checkDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) {
        continue; 
      }

      let noonStart = new Date(checkDate);
      noonStart.setHours(12, 0, 0, 0);
      let noonEnd = new Date(checkDate);
      noonEnd.setHours(13, 0, 0, 0);

      for (let hour = 9; hour <= 16; hour++) {
        for (let min = 0; min < 60; min += 30) {

          let meetingStart = new Date(checkDate);
          meetingStart.setHours(hour, min, 0, 0);

          let meetingEnd = new Date(meetingStart);
          meetingEnd.setMinutes(meetingStart.getMinutes() + Number(durationMin));

          if (Number(durationMin) === 240) {
            if (!(hour === 9 && min === 0) && !(hour === 14 && min === 0)) {
              continue;
            }
          } else {
            if (meetingStart < noonEnd && meetingEnd > noonStart) {
              continue;
            }
          }

          let checkStart = new Date(meetingStart);
          checkStart.setMinutes(meetingStart.getMinutes() - bufferMin);

          let checkEnd = new Date(meetingEnd);
          checkEnd.setMinutes(meetingEnd.getMinutes() + bufferMin);

          let isAvailable = true;

          for (let m = 0; m < allMemberEvents.length; m++) {
            let events = allMemberEvents[m];
            for (let e = 0; e < events.length; e++) {
              let evStart = events[e].getStartTime();
              let evEnd = events[e].getEndTime();

              if (evStart < checkEnd && evEnd > checkStart) {
                isAvailable = false;
                break;
              }
            }
            if (!isAvailable) break;
          }

          if (isAvailable) {
             let dateStr = Utilities.formatDate(meetingStart, 'JST', 'yyyy/MM/dd');
             let startStr = Utilities.formatDate(meetingStart, 'JST', 'HH:mm');
             let endStr = Utilities.formatDate(meetingEnd, 'JST', 'HH:mm');

             let dayStr = ['(日)', '(月)', '(火)', '(水)', '(木)', '(金)', '(土)'][dayOfWeek];
             resultSheet.appendRow([meetingName, dateStr + ' ' + dayStr, startStr, endStr, members.join(', ')]);

             firstFoundDate = new Date(meetingStart);
             break; 
          }
        }
        if (firstFoundDate) break; 
      }
      if (firstFoundDate) break; 
    }

    if (!firstFoundDate) {
      resultSheet.appendRow([meetingName, '※この期間に全員の土日の空きがありませんでした', '', '', members.join(', ')]);
      baseDate = new Date(searchStartDay);
    } else {
      baseDate = new Date(firstFoundDate);
    }
  }
}
